<?php
namespace App\Services;
use App\Models\{AttendanceRecord,AttendanceSession,SchoolClass,User};
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
class AttendanceService {public function save(User $actor,SchoolClass $class,array $rows):AttendanceSession {abort_unless($actor->hasRole('teacher') && $actor->teacher?->currentAssignment?->class_id===$class->id,403);return DB::transaction(function()use($actor,$class,$rows){$session=AttendanceSession::firstOrCreate(['class_id'=>$class->id,'attendance_date'=>today(config('app.timezone'))],['school_id'=>$class->school_id,'teacher_id'=>$actor->teacher->id]);if($session->isLocked())throw ValidationException::withMessages(['attendance'=>['Attendance locked at 9:00 AM.']]);foreach($rows as $row){$student=$class->students()->findOrFail($row['student_id']);AttendanceRecord::updateOrCreate(['attendance_session_id'=>$session->id,'student_id'=>$student->id],['status'=>$row['status']]);}$session->update(['status'=>'in_progress']);return $session;});}public function submit(User $actor,AttendanceSession $session):void {abort_unless($actor->hasRole('teacher')&&$actor->teacher?->currentAssignment?->class_id===$session->class_id,403);if($session->isLocked())throw ValidationException::withMessages(['attendance'=>['Attendance locked at 9:00 AM.']]);$count=$session->records()->count();if($count!==$session->schoolClass->students()->where('status','active')->count())throw ValidationException::withMessages(['attendance'=>['Every active student must be marked.']]);$session->update(['status'=>'submitted','submitted_at'=>now()]);app(SmsService::class)->queueAbsent($session);}}
